function lpAdd(){const t=$("#a").value.trim(),d=+$("#d").value||50,o=$("#c").value.split("\n").map(x=>x.trim()).filter(Boolean),f=$("#f").value.split("\n").map(x=>x.trim()).filter(Boolean);if(!t)return toast("Enter the topic");const I=[`Prepare slides and examples on ${t}`,`Recap and hook (${Math.round(d*.1)} min)`,...o.map(x=>`Teach: ${x}`),...f.map(x=>`Activity: ${x}`),`Check understanding with 3 questions (${Math.round(d*.15)} min)`,"Share notes and homework"].map(x=>({t:x,done:false}));DB.lps.unshift({id:Date.now(),topic:t,cls:$("#b").value,d,items:I});sv();lpr();toast("To-do list created")}
