R.rl=function(){const g=DB.wa||{};m.innerHTML=hd("Send your Google Form link to students, then bring the answers in")+`<div class="card np"><h3>Registration link</h3><label>Your Google Form link<input id="rf" value="${e(g.form)}" placeholder="https://forms.gle/..." onchange="rfSave(this.value)"></label>${waBox()}<button class="gn" onclick="rlSend()">Send link on WhatsApp</button><button class="g" onclick="rlGroup()">Copy message and open group</button><span id="rlo"></span><p class="mu">Students open your Google Form and fill it. After they submit, bring their answers in below.</p></div><div class="card np"><h3>Bring in the form answers</h3><p class="mu">In Google Forms open Responses, then Link to Sheets, then File, Download, CSV. Choose the file here. The students are added to Batch folders.</p><div class="row"><label>Batch (if the form has no batch question)<input id="ib"></label><label>Department (if the form has none)<input id="idp"></label></div><label>Answer files (CSV)<input type="file" id="if" multiple accept=".csv,.tsv,.txt"></label><label>Or paste rows copied from Google Sheets<textarea id="ip" rows="3"></textarea></label><button onclick="P_impS()">Add students</button><button class="g" onclick="go('ps')">Open student folders</button><div id="r1"></div></div>`};
async function rlCopy(){try{await navigator.clipboard.writeText(rlLink());toast("Link copied")}catch(x){toast("Copy blocked. Select the link and copy it.")}}
async function rlGroup(){if(!rlLink()||!(DB.wa||{}).link)return toast("Paste the Google Form link and the group link first");try{await navigator.clipboard.writeText(rlMsg())}catch(x){toast("Copy blocked. Use Send on WhatsApp.");return}$("#rlo").innerHTML=` <button onclick="window.open('${e(DB.wa.link)}','_blank','noopener')">Open group now</button> <span class="ok">Message copied. Paste it in the group.</span>`}
async function rlAdd(){const P=$("#rr").value.split(/REGISTRATION/).slice(1),KM={"name":"name","date of birth":"dob","gender":"gender","address":"address","student phone":"phone","parent phone":"parentPhone","email":"email","admission number":"admNo","register number":"regNo","department":"dept","course":"course","batch":"batch","current year":"year","current semester":"sem","school name":"school","board":"board","year of passing":"yop","father name":"father","mother name":"mother"},A=[];
P.forEach(b=>{const r={extra:{}};b.split("\n").forEach(l=>{const x=l.match(/^\s*([A-Za-z ]+?):\s*(.+)$/),k=x&&KM[x[1].trim().toLowerCase()];if(k)r[k]=x[2].trim()});if(r.regNo&&r.name)A.push(r)});
if(!A.length){$("#rro").innerHTML='<p class="bad">No registrations found. Paste the messages that start with REGISTRATION.</p>';return}
const n=await P_merge(A);$("#rro").innerHTML=`<p class="ok">${A.length} registrations read: ${n} new, ${A.length-n} updated. Open Student folders to see them.</p><p class="mu">Photos: students send them in WhatsApp. Add each one from Add student.</p>`}
function attPct(s){const L=DB.alog.filter(x=>x.batch==s.batch);if(L.length)return(L.length-L.filter(x=>x.absent.includes(s.reg)).length)/L.length*100;return s.held?s.att/s.held*100:100}
R.at=function(){const bs=[...new Set(DB.students.map(s=>s.batch).filter(Boolean))].sort();m.innerHTML=hd("Store attendance by voice, text or by hand, then see the analysis")+`<div class="card np"><div class="row"><label>Batch<select id="ab" onchange="atr()">${bs.map(b=>`<option>${e(b)}</option>`).join("")}</select></label><label>Date<input id="ad" type="date" value="${off(0)}" onchange="atr()"></label><label>Shortage below (%)<input id="th" type="number" value="75" oninput="atr(false)"></label></div><div class="ag"><input id="q" placeholder="e.g. Arun and Bala absent, Dinesh late" onkeydown="if(event.key=='Enter')attAsk()"><button onclick="attAsk()">Mark</button></div><div id="ans"></div><p class="mu">Everyone you do not name is marked present. Say it in Tamil, Tanglish or English.</p></div><div class="card np" id="mk"></div><div class="card" id="atb"></div>`;atr()};
function atr(k){if(k!==false)mkr();const b=$("#ab")?$("#ab").value:"",th=+$("#th").value||75,S=DB.students.filter(s=>s.batch==b),L=DB.alog.filter(x=>x.batch==b).sort((x,y)=>x.date<y.date?1:-1);
$("#atb").innerHTML=S.length?`<div class="np" style="text-align:right"><button class="g" onclick="print()">Print</button><button class="g" onclick="attShare()">Share shortage list</button></div>${attCh(S,L,th)}<div class="tw"><table><tr><th>Name</th><th>Register no.</th><th>Days held</th><th>Absent</th><th>Late</th><th>Attendance %</th><th>Status</th></tr>${S.map(s=>{const ab=L.filter(x=>x.absent.includes(s.reg)).length,lt=L.filter(x=>(x.late||[]).includes(s.reg)).length,p=attPct(s);return `<tr><td>${e(s.name)}</td><td>${e(s.reg)}</td><td>${L.length}</td><td>${ab}</td><td>${lt}</td><td>${p.toFixed(1)}</td><td class="${p<th?"bad":"ok"}">${p<th?"Shortage":"OK"}</td></tr>`}).join("")}</table></div>${L.length?`<h4>Recent days</h4>${L.slice(0,8).map(x=>`<p>${x.date}: ${x.absent.length} absent${x.absent.length?" ("+e(x.absent.join(", "))+")":""}, ${(x.late||[]).length} late <button class="x np" onclick="attDel('${x.date}')">Delete</button></p>`).join("")}`:'<p class="mu">No days recorded yet. Tell the agent who is absent above.</p>'}`:'<p class="mu">No students in this batch yet. Add students first.</p>'}
function mkr(){const o=$("#mk");if(!o)return;const b=$("#ab").value,d=$("#ad").value,S=DB.students.filter(s=>s.batch==b),x=DB.alog.find(y=>y.date==d&&y.batch==b)||{absent:[],late:[]};
o.innerHTML=S.length?`<h3>Mark by hand</h3><p class="mu">Choose for each student, then save the day. Saving the same date again replaces it.</p><div class="tw"><table><tr><th>Name</th><th>Register no.</th><th>Status</th></tr>${S.map(s=>`<tr><td>${e(s.name)}</td><td>${e(s.reg)}</td><td><select class="ms" data-r="${e(s.reg)}" style="margin:0;width:auto"><option>Present</option><option ${x.absent.includes(s.reg)?"selected":""}>Absent</option><option ${(x.late||[]).includes(s.reg)?"selected":""}>Late</option></select></td></tr>`).join("")}</table></div><button onclick="mkSave()">Save this day</button><button class="g" onclick="document.querySelectorAll('.ms').forEach(s=>s.value='Present')">All present</button>`:""}
function mkSave(){const b=$("#ab").value,d=$("#ad").value,ab=[],lt=[];document.querySelectorAll(".ms").forEach(s=>{if(s.value=="Absent")ab.push(s.dataset.r);else if(s.value=="Late")lt.push(s.dataset.r)});DB.alog=DB.alog.filter(y=>!(y.date==d&&y.batch==b));DB.alog.push({date:d,batch:b,absent:ab,late:lt});sv();atr();toast("Saved "+d+": "+ab.length+" absent")}
function attCh(S,L,th){if(!L.length||!S.length)return"";const D=L.slice(0,10).reverse(),w=48;return `<h4>Daily attendance</h4><svg viewBox="0 0 ${D.length*w+10} 110" style="width:100%;max-width:${D.length*w+10}px">${D.map((x,i)=>{const p=(S.length-x.absent.length)/S.length*100,h=p*.7;return `<rect x="${i*w+8}" y="${80-h}" width="34" height="${h}" rx="3" fill="${p<th?"var(--ac2)":"var(--ac)"}"/><text x="${i*w+25}" y="${75-h}" text-anchor="middle" font-size="10" fill="currentColor">${p.toFixed(0)}</text><text x="${i*w+25}" y="96" text-anchor="middle" font-size="9" fill="currentColor">${x.date.slice(5)}</text>`}).join("")}</svg>`}
function attDel(d){DB.alog=DB.alog.filter(x=>!(x.date==d&&x.batch==$("#ab").value));sv();atr()}
function attShare(){const b=$("#ab").value,th=+$("#th").value||75,L=DB.students.filter(s=>s.batch==b&&attPct(s)<th);window.open("https://wa.me/?text="+encodeURIComponent("Attendance shortage, batch "+b+" (below "+th+"%)\n"+(L.map(s=>s.name+" ("+s.reg+"): "+attPct(s).toFixed(1)+"%").join("\n")||"None")),"_blank","noopener")}
async function attAsk(){const q=$("#q").value.trim(),a=$("#ans"),b=$("#ab").value,d=$("#ad").value;if(!q||!b||!d)return toast("Choose the batch and date, then say who is absent");const S=DB.students.filter(s=>s.batch==b);
const fin=(ab,lt)=>{const res=r=>[...new Set(r.map(x=>{x=String(x);const s=S.find(s=>s.reg.toLowerCase()==x.toLowerCase())||(x.length>=3&&S.find(s=>s.name.toLowerCase().includes(x.toLowerCase())));if(!s)throw new Error("No student matches “"+x+"” in "+b);return s.reg}))],A=res(ab),T=res(lt).filter(x=>!A.includes(x));DB.alog=DB.alog.filter(x=>!(x.date==d&&x.batch==b));DB.alog.push({date:d,batch:b,absent:A,late:T});sv();atr();return A.length+" absent, "+T.length+" late, "+(S.length-A.length)+" present"};
a.innerHTML='<p style="margin-top:10px"></p>';const p=a.firstChild;p.textContent="Marking...";const sm=window.claude?await claude.use("sample"):null;
if(sm){try{const r=await sm([{role:"user",content:"You mark class attendance. Students of batch "+b+": "+S.map(s=>s.name+" ("+s.reg+")").join(", ")+". The teacher said: \""+q+"\". Call mark_attendance once with the absent and late students. Everyone not mentioned is present. Then confirm in one short sentence in the teacher's language."}],{cache:false,tools:[{name:"mark_attendance",description:"Save attendance for the chosen batch and date",inputSchema:{type:"object",properties:{absent:{type:"array",items:{type:"string"},description:"names or register numbers"},late:{type:"array",items:{type:"string"}}},required:["absent"]},execute:i=>fin(i.absent||[],i.late||[])}],onText:x=>{p.textContent=x.text}});p.textContent=r.text||"Attendance saved.";return}catch(x){p.textContent="Marking..."}}
try{const cl=q.toLowerCase().split(/[,;]|\band\b/),ab=[],lt=[];S.forEach(s=>{const c=cl.find(c=>c.includes(s.name.toLowerCase())||c.includes(s.reg.toLowerCase()));if(!c||(/present/.test(c)&&!/absent/.test(c)))return;(/late/.test(c)?lt:ab).push(s.reg)});if(!ab.length&&!lt.length)throw new Error("No student from this batch found in your message");p.textContent="Saved: "+fin(ab,lt)}catch(x){p.textContent=x.message}}
R.nt=function(){m.innerHTML=hd("Give the syllabus and get student notes, then send them on WhatsApp")+`<div class="card np"><div class="row"><label>Subject<input id="ns" value="Data Structures"></label><label>Class<input id="nc" value="II CSE"></label><label>Language<select id="nl"><option>English</option><option>Tamil</option></select></label></div><label>Syllabus (paste the units and topics)<textarea id="ny" rows="6"></textarea></label><label>Or choose a text file<input type="file" accept=".txt,.md" onchange="ntFile(this)"></label><button onclick="ntGen()">Make notes</button></div><div class="card"><h3>Notes</h3><label>Read and edit before sending<textarea id="nx" class="doc" style="min-height:300px" oninput="DB.ntx=this.value;ntUnits()">${e(DB.ntx)}</textarea></label><div class="np">${waBox()}<label>Send<select id="nu"></select></label><button class="gn" onclick="ntSend()">Send on WhatsApp</button><button class="g" onclick="ntGroup()">Copy and open group</button><button class="rd" onclick="ntPdf()">PDF</button><button class="g" onclick="print()">Print</button><span id="nco"></span></div></div>`;ntUnits()};
function ntFile(i){const f=i.files[0];if(f)f.text().then(t=>$("#ny").value=t)}
function ntParts(){const t=$("#nx").value,i=[...t.matchAll(/^UNIT\s*\d+[^\n]*/gim)].map(x=>x.index);return i.length?i.map((s,k)=>t.slice(s,i[k+1]??t.length).trim()):[t]}
function ntUnits(){const p=ntParts();$("#nu").innerHTML='<option value="-1">All notes</option>'+p.map((x,k)=>`<option value="${k}">${e(x.split("\n")[0].slice(0,40))}</option>`).join("")}
const ntMsg=()=>{const v=+$("#nu").value,t=(v<0?$("#nx").value:ntParts()[v]).trim();return "📚 "+$("#ns").value+" notes ("+$("#nc").value+")\n\n"+t};
async function ntGen(){const y=$("#ny").value.trim();if(!y)return toast("Paste the syllabus first");const sm=window.claude?await claude.use("sample"):null;if(!sm)return toast("The AI agent is not available here. Open the page in the Claude app or a browser.");const x=$("#nx");x.value="Preparing notes...";
try{const r=await sm("You are a teaching assistant in a college. Using only this syllabus, write clear study notes for "+$("#nc").value+" students in "+$("#ns").value+". For every unit give a heading line like UNIT 1: Title, then 5 to 8 short bullet points starting with '- ', one simple example or analogy, and 3 revision questions. Plain text only. No markdown symbols such as * or #. Keep each unit under 250 words. Write in "+$("#nl").value+".\n\nSYLLABUS:\n"+y,{cache:false,onText:t=>{x.value=t.text}});x.value=r.text;DB.ntx=r.text;sv();ntUnits()}catch(z){x.value=DB.ntx;toast(z.code=="not_granted"?"Permission for the AI agent was declined":"The agent could not finish. Try again.")}}
function ntSend(){const t=ntMsg();if(t.length>3000)return toast("This is long for one WhatsApp message. Choose one unit in Send.");window.open("https://wa.me/?text="+encodeURIComponent(t),"_blank","noopener")}
async function ntGroup(){if(!(DB.wa||{}).link)return toast("Paste your students’ group link above first");try{await navigator.clipboard.writeText(ntMsg())}catch(x){return toast("Copy blocked. Use Send on WhatsApp.")}$("#nco").innerHTML=` <button onclick="window.open('${e(DB.wa.link)}','_blank','noopener')">Open group now</button> <span class="ok">Copied. Paste it in the group.</span>`}
async function ntPdf(){const t=$("#nx").value.trim();if(!t)return toast("Make or paste the notes first");if(/[\u0B80-\u0BFF]/.test(t))return toast("Tamil notes can be sent as text. The PDF supports English only.");if(!window.jspdf)return toast("PDF library did not load. Check your connection.");const d=new jspdf.jsPDF();d.setFontSize(16);d.text($("#ns").value+" notes ("+$("#nc").value+")",14,16);d.setFontSize(11);let y=26;d.splitTextToSize(t,180).forEach(l=>{if(y>280){d.addPage();y=16}d.text(l,14,y);y+=6});
const b=d.output("blob"),f=new File([b],"notes.pdf",{type:"application/pdf"});try{if(navigator.canShare&&navigator.canShare({files:[f]})){await navigator.share({files:[f],text:$("#ns").value+" notes"});return}}catch(x){if(x.name=="AbortError")return}await bfSave(b,"notes.pdf")}
