const TT=()=>DB.tt.split("\n").filter(l=>l.split(":").length==3&&l.split(":")[0].trim());
R.tt=function(){m.innerHTML=hd("Add each teacher once. The timetable is built without clashes")+`<div class="card np ttbox"><h3>Who teaches what</h3><div class="ttrow"><label>Staff name<input id="tn" placeholder="Dr. Anand" onkeydown="if(event.key=='Enter')$('#ts').focus()"></label><label>Subject<input id="ts" placeholder="Data Structures" onkeydown="if(event.key=='Enter')$('#tc').focus()"></label><label>Class<input id="tc" placeholder="CSE" onkeydown="if(event.key=='Enter')ttAdd()"></label><button onclick="ttAdd()">Add</button></div><div class="ttl" id="ttl"></div><button class="gn" onclick="genTT();toast('Timetable generated')">Generate timetable</button><button class="g" onclick="print()">Print as PDF</button></div><div id="out"></div>`;ttl();genTT()};
function ttl(){const L=TT().map(l=>l.split(":").map(s=>s.trim()));$("#ttl").innerHTML=L.length?L.map((a,i)=>`<div class="chip" data-k="${i%4}"><b>${e(a[0])}</b><span>${e(a[1])}</span><em>${e(a[2])}</em><button class="x np" onclick="ttDel(${i})" aria-label="Remove ${e(a[0])}">✕</button></div>`).join(""):'<p class="mu">No teachers yet. Add a name, subject and class above.</p>'}
function ttAdd(){const n=$("#tn").value.trim(),s=$("#ts").value.trim(),c=$("#tc").value.trim();if(!n||!s||!c)return toast("Fill the staff name, subject and class");if([n,s,c].some(x=>x.includes(":")))return toast("Please remove the colon (:) from the text");DB.tt=TT().concat([n+":"+s+":"+c]).join("\n");sv();["tn","ts","tc"].forEach(k=>$("#"+k).value="");ttl();genTT();$("#tn").focus()}
function ttDel(i){const L=TT();L.splice(i,1);DB.tt=L.join("\n");sv();ttl();genTT()}
const PVB=[["முயற்சி திருவினை ஆக்கும்.","Effort brings good fortune. (Thirukkural)"],["கற்றது கைமண் அளவு, கல்லாதது உலகளவு.","What we have learned is a handful; what we have not is the size of the world."],["அடிமேல் அடி வைத்தால் அம்மியும் நகரும்.","Step after step, even a grinding stone moves."],["சிறு துளி பெருவெள்ளம்.","Little drops make a flood."],["காலம் பொன் போன்றது.","Time is like gold."],["ஒற்றுமையே பலம்.","Unity is strength."],["இளமையில் கல்.","Learn while you are young. (Aathichudi)"],["வாய்மையே வெல்லும்.","Truth alone triumphs."],["எண்ணும் எழுத்தும் கண்ணெனத் தகும்.","Numbers and letters are the two eyes of life."],["பொறுமை கடலினும் பெரிது.","Patience is greater than the ocean."],["A journey of a thousand miles begins with a single step.",""],["Well begun is half done.",""],["Practice makes perfect.",""],["Where there is a will, there is a way.",""],["Slow and steady wins the race.",""],["Knowledge is power.",""],["Little strokes fell great oaks.",""],["Do not put off until tomorrow what you can do today.",""],["A stitch in time saves nine.",""],["Rome was not built in a day.",""],["Experience is the best teacher.",""],["Many hands make light work.",""],["Every day is a fresh start.",""],["Fall seven times, stand up eight.",""],["The expert in anything was once a beginner.",""],["கற்க கசடறக் கற்பவை கற்றபின் நிற்க அதற்குத் தக.","Learn well, then live by what you have learned. (Thirukkural)"],["உழைப்பே உயர்வு தரும்.","Hard work lifts you up."],["Quality is better than quantity.",""],["Be the change you wish to see.",""],["Small steps every day lead to big results.",""]];
const PV=()=>{const d=new Date(),i=Math.floor((d-new Date(d.getFullYear(),0,0))/864e5)%PVB.length,p=PVB[i];return `<q>${e(p[0])}</q>${p[1]?`<small>${e(p[1])}</small>`:""}`};
const qpBlob=f=>new Promise(r=>{const fr=new FileReader();fr.onload=()=>{const im=new Image();im.onload=()=>{const k=Math.min(1,1600/Math.max(im.width,im.height)),c=document.createElement("canvas");c.width=im.width*k;c.height=im.height*k;c.getContext("2d").drawImage(im,0,0,c.width,c.height);c.toBlob(b=>r(b),"image/jpeg",.85)};im.onerror=()=>r(null);im.src=fr.result};fr.onerror=()=>r(null);fr.readAsDataURL(f)});
let qCtl=null;
R.qp=function(){m.innerHTML=hd("Give the syllabus and the template. The agent writes the paper in that layout")+`<div class="card np"><div class="row"><label>Subject<input id="qs" placeholder="Data Structures"></label><label>Class and semester<input id="qc" placeholder="II CSE, Semester 3"></label></div><label>Question paper template (photo or screenshot)<input type="file" id="qt" accept="image/*"></label><label>Syllabus (photos of the pages)<input type="file" id="qy" accept="image/*" multiple></label><label>Or paste the syllabus text<textarea id="qx" rows="4"></textarea></label><label>Previous question papers, so questions are not repeated (optional)<input type="file" id="qv" accept="image/*" multiple></label><label>Anything else the agent should know (optional)<input id="qn" placeholder="Easy to medium, more problems from Unit 3"></label><button onclick="qpGo()">Create question paper</button><button class="g" id="qst" onclick="if(qCtl)qCtl.abort()" style="display:none">Stop</button> <span class="mu" id="qms"></span></div><div class="card np"><h3>Edit the text if you want</h3><textarea id="qo" rows="10" oninput="qpShow()"></textarea><button onclick="qpPrint()">Print</button></div><div class="card pcard"><div class="paper" id="pap"></div></div>`;qpShow()};
async function qpGo(){const sm=window.claude?await claude.use("sample"):null;if(!sm)return toast("The AI agent is not available here. Open the page in the Claude app or a browser.");
const T=$("#qt").files[0],Y=[...$("#qy").files],P=[...$("#qv").files],tx=$("#qx").value.trim(),all=[...(T?[T]:[]),...Y,...P];
if(!Y.length&&!tx)return toast("Add the syllabus as photos or paste its text");
const caps=await sm.limits().catch(()=>null);if(all.length&&!(caps&&caps.images))return toast("Photo upload is not available here. Paste the syllabus text instead.");if(all.length&&all.length>caps.images.maxCount)return toast("Too many pictures. Use at most "+caps.images.maxCount+" in total.");
const ms=$("#qms"),o=$("#qo"),st=$("#qst");ms.textContent="Reading the pictures and writing the paper...";st.style.display="";qCtl=new AbortController();
const B=[];for(const f of all){const b=await qpBlob(f);if(!b){ms.textContent="";st.style.display="none";return toast("One picture could not be read. Use a clear JPG or PNG.")}B.push(b)}
let n=1;const ds=[T?"Image 1 is the question paper template.":"There is no template picture, so use a standard format: heading, time and maximum marks, instructions, Part A short questions (2 marks) and Part B long questions (13 marks).",Y.length?"Images "+(T?2:1)+" to "+((T?1:0)+Y.length)+" are pages of the syllabus.":"",P.length?"The last "+P.length+" image(s) are previous question papers. Do not repeat their questions.":""].filter(Boolean).join(" ");
const pr="You are an exam paper setter in a college. Subject: "+($("#qs").value||"not given")+". Class: "+($("#qc").value||"not given")+". "+ds+" Read the template carefully and copy its layout: heading lines, exam title, time and maximum marks, instructions, the parts and sections, the number of questions in each and the marks for each. Write NEW questions only from the syllabus, spread fairly across all units, with no repeated questions, at a suitable level. Output plain text only with no markdown symbols. A line starting with '# ' is a centred heading. A line starting with '## ' is a section heading. Put the marks of a question at the end of its line in square brackets such as [2]. Number the questions 1, 2, 3. "+($("#qn").value?"Extra notes: "+$("#qn").value+". ":"")+(tx?"\n\nSYLLABUS TEXT:\n"+tx:"");
try{const r=await sm(pr,{images:B.length?B:undefined,cache:false,signal:qCtl.signal,onText:t=>{o.value=t.text;qpShow()}});o.value=r.text;qpShow();toast("Question paper ready. Check it, then print.")}catch(x){if(x.text)o.value=x.text;qpShow();toast({not_granted:"Permission for the AI agent was declined",cancelled:"Stopped",images_unavailable:"Photo upload is not available here. Paste the syllabus text instead.",image_rejected:"A picture could not be read. Use a clear JPG or PNG.",rate_limited:"Too many requests. Wait a minute and try again."}[x.code]||"The agent could not finish. Try again.")}finally{ms.textContent="";st.style.display="none";qCtl=null}}
function qpShow(){const o=$("#pap");if(!o)return;o.textContent="";const L=($("#qo").value||"").split("\n");if(!L.join("").trim()){const p=document.createElement("p");p.className="mu";p.textContent="The question paper appears here.";o.appendChild(p);return}
L.forEach(l=>{const d=document.createElement("div");let t=l;if(t.startsWith("## ")){d.className="ps";t=t.slice(3)}else if(t.startsWith("# ")){d.className="pc";t=t.slice(2)}const k=t.match(/^(.*?)\s*\[(\d+)\]\s*$/);if(k&&!d.className){d.className="pq";const a=document.createElement("span"),b=document.createElement("b");a.textContent=k[1];b.textContent="["+k[2]+"]";d.append(a,b)}else d.textContent=t||"\u00a0";o.appendChild(d)})}
function qpPrint(){if(!$("#qo").value.trim())return toast("Create the question paper first");const b=document.body.classList;b.add("pp");const f=()=>{b.remove("pp");removeEventListener("afterprint",f)};addEventListener("afterprint",f);setTimeout(f,4000);print()}
